B3=()
for x in "${B3_REPOS[@]}"; do
  set -- $x
  B3+=(--repo "$1=$2" --ref "$1=$3" --commit "$1=$4")
done
for x in "${B3_PACKAGES[@]}"; do
  set -- $x
  B3+=(--package-at "$1=$2" --module "$1=$3" --package "$1")
done
