# ublox_msgs: the padding fields of the u-blox layouts (named reserved, an optional underscore and a number)
# hold no value and are not mapped.
B3+=(--skip-field-re 'ublox_msgs=^reserved_?[0-9]*$')
# px4_msgs: six kinds state a WGS 84 position (evidence in notes/ros2-px4-msgs.md).
P=px4_msgs
B3+=(--map $P/SensorGnss:latitude=lat --map $P/SensorGnss:longitude=lon --map $P/SensorGnss:altitude_ellipsoid=hae --cross $P/SensorGnss
     --map $P/VehicleGlobalPosition:lat=lat --map $P/VehicleGlobalPosition:lon=lon --map $P/VehicleGlobalPosition:alt_ellipsoid=hae --cross $P/VehicleGlobalPosition
     --map $P/HomePosition:lat=lat --map $P/HomePosition:lon=lon --cross $P/HomePosition
     --map $P/AuxGlobalPosition:lat=lat --map $P/AuxGlobalPosition:lon=lon --cross $P/AuxGlobalPosition
     --map $P/TargetGnss:latitude_deg=lat --map $P/TargetGnss:longitude_deg=lon --cross $P/TargetGnss
     --map $P/CameraCapture:lat=lat --map $P/CameraCapture:lon=lon --cross $P/CameraCapture)

